-- ts-analytics 1.0.0 – zobrazení stránek a události (SQLite). Bez IP adresy; návštěvník a návštěva jen jako náhodná ID z cookies (po souhlasu).
CREATE TABLE IF NOT EXISTS ts_an_hits (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, day VARCHAR(10) NOT NULL, vid VARCHAR(16) NOT NULL, sid VARCHAR(16) NOT NULL, newv INTEGER NOT NULL DEFAULT 0, kind VARCHAR(2) NOT NULL, path VARCHAR(200) NOT NULL DEFAULT '', ref VARCHAR(100) NOT NULL DEFAULT '', src VARCHAR(60) NOT NULL DEFAULT '', med VARCHAR(60) NOT NULL DEFAULT '', camp VARCHAR(80) NOT NULL DEFAULT '', lang VARCHAR(8) NOT NULL DEFAULT '', dev VARCHAR(1) NOT NULL DEFAULT '', br VARCHAR(12) NOT NULL DEFAULT '', os VARCHAR(12) NOT NULL DEFAULT '', ev VARCHAR(40) NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS ts_an_hits_day ON ts_an_hits (day);
CREATE INDEX IF NOT EXISTS ts_an_hits_sid ON ts_an_hits (sid, ts);
CREATE TABLE IF NOT EXISTS ts_an_rate (bucket VARCHAR(120) NOT NULL PRIMARY KEY, window_start INTEGER NOT NULL, count INTEGER NOT NULL DEFAULT 0);
